void cancel_device_pending(std::uint64_t ticket) {
    require_device_pending_ticket(ticket);
    phase_=Phase::executing;
    try {
        restore_device_pending_root(false);
        clear_device_pending();
        phase_=Phase::ready;
    } catch(...) {
        clear_device_pending();
        phase_=Phase::poisoned;
        throw;
    }
}
```

